import type { BuiltTable } from './read-built-tables';

export function renderTableTypes(tables: readonly BuiltTable[]): string {
  const lines = [
    '// Generated by `bun run --cwd libs/db tables` from the migrations in nixieSchema. Do not edit.',
    "// A module's table types check against it through CheckedTables.",
    'export interface NixieTables {',
  ];

  for (const table of tables) {
    lines.push(`  readonly ${table.name}: {`);

    for (const column of table.columns) {
      const type = toColumnType(table.name, column.name, column.type);

      lines.push(`    readonly ${column.name}: ${column.isNullable ? `${type} | null` : type};`);
    }

    lines.push('  };');
  }

  lines.push('}', '');

  return lines.join('\n');
}

const columnTypes: Readonly<Record<string, string>> = {
  integer: 'number',
  real: 'number',
  text: 'string',
  blob: 'Uint8Array<ArrayBuffer>',
};

function toColumnType(table: string, column: string, declared: string): string {
  const type = columnTypes[declared];

  if (type === undefined) {
    throw new Error(
      `${table}.${column} has the column type '${declared}', which has no TypeScript type`,
    );
  }

  return type;
}
